select id, shipped_date, status, delivered_date, cost, order_id, carrier, sum(cost) over (partition by year(shipped_date), status order by delivered_date, id rows between unbounded preceding and current row) as running_cost, last_value(carrier) over (partition by order_id order by delivered_date desc, id rows between unbounded preceding and unbounded following) as last_carrier from shipments where cost > 90 order by shipped_date asc;
